//! Calendar on a proleptic Gregorian grid.
pub use crate::primitives::form_dates::{CivilDate, DateSpan};
use crate::primitives::form_dates::{DateControl, DateLayout};
pub struct CalendarLayout;
impl DateLayout for CalendarLayout {
    const FIELD: bool = false;
    const RANGE: bool = false;
}
pub type Calendar = DateControl<CalendarLayout>;

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

//! Shared labelled controls for the form family.
use super::{
    control::UiLanguage,
    family::{Paint, Tone, face},
    glyph::{Glyph, icon},
};
use gpui::{prelude::*, *};
pub fn tr(cx: &App, en: &'static str, zh: &'static str) -> &'static str {
    UiLanguage::current(cx).text(en, zh)
}
pub fn col() -> Div {
    div().flex().flex_col().min_w_0().gap(px(8.))
}
pub fn row() -> Div {
    div().flex().items_center().min_w_0().gap(px(8.))
}
pub fn section(width: f32, cx: &App) -> Div {
    col()
        .w(px(width))
        .max_w_full()
        .text_size(px(14.))
        .line_height(px(20.))
        .text_color(Paint::get(cx).ink)
}
pub fn panel(cx: &App) -> Div {
    col()
        .rounded(crate::foundation::surface_radius(cx))
        .border_1()
        .border_color(Paint::get(cx).line)
        .bg(Paint::get(cx).panel)
        .p(px(8.))
}
pub fn hint(text: impl Into<SharedString>, cx: &App) -> Div {
    div()
        .text_size(px(12.))
        .line_height(px(17.))
        .text_color(Paint::get(cx).faint)
        .child(text.into())
}
pub fn button(id: impl Into<ElementId>, name: impl Into<SharedString>, cx: &App) -> Stateful<Div> {
    let n = name.into();
    let p = Paint::get(cx);
    face(
        id,
        n.clone(),
        32.,
        crate::foundation::surface_radius(cx).into(),
        Tone::Clear,
        cx,
    )
    .px(px(9.))
    .hover(move |s| s.bg(p.hover))
    .when(!n.is_empty(), |button| button.child(n))
}
pub fn glyph(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    g: Glyph,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    face(
        id,
        label,
        32.,
        crate::foundation::surface_radius(cx).into(),
        Tone::Clear,
        cx,
    )
    .w(px(32.))
    .hover(move |s| s.bg(p.hover))
    .child(icon(g, 16., p.secondary))
}
pub fn field(id: impl Into<ElementId>, name: impl Into<SharedString>, cx: &App) -> Stateful<Div> {
    let p = Paint::get(cx);
    face(
        id,
        name,
        44.,
        crate::foundation::surface_radius(cx).into(),
        Tone::Clear,
        cx,
    )
    .justify_between()
    .px(px(12.))
    .border_1()
    .border_color(p.line)
    .bg(p.panel)
    .hover(move |s| s.border_color(p.faint))
}

/// Calendar outline kept separate from the time-of-day glyph.
pub fn calendar_mark(ink: Hsla) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| b.origin + point(px(x), px(y));
            let mut path = PathBuilder::stroke(px(1.4));
            path.move_to(at(2., 4.));
            path.line_to(at(14., 4.));
            path.line_to(at(14., 14.));
            path.line_to(at(2., 14.));
            path.line_to(at(2., 4.));
            path.move_to(at(2., 7.));
            path.line_to(at(14., 7.));
            path.move_to(at(5., 2.));
            path.line_to(at(5., 5.));
            path.move_to(at(11., 2.));
            path.line_to(at(11., 5.));
            if let Ok(path) = path.build() {
                w.paint_path(path, ink)
            }
        },
    )
    .size(px(16.))
}

/// The same panel stays mounted during exit. Its unclipped inner stack supplies the
/// natural height even when the outer reveal is a single pixel tall.
pub struct FormReveal {
    spring: super::family::Slide,
    anchor: std::rc::Rc<std::cell::Cell<Bounds<Pixels>>>,
    panel_bounds: std::rc::Rc<std::cell::Cell<Bounds<Pixels>>>,
    visible: bool,
    above: bool,
    alpha_start: f32,
    alpha: f32,
    fade: super::family::PhaseClock,
    height: std::rc::Rc<std::cell::Cell<Pixels>>,
}
impl FormReveal {
    pub fn new(visible: bool) -> Self {
        Self {
            spring: super::family::Slide::snappy(visible as u8 as f32),
            anchor: Default::default(),
            panel_bounds: Default::default(),
            visible,
            above: false,
            alpha_start: visible as u8 as f32,
            alpha: visible as u8 as f32,
            fade: Default::default(),
            height: Default::default(),
        }
    }
    pub fn sample(&mut self, open: bool, enter: f32, exit: f32, w: &Window, cx: &App) -> f32 {
        if self.visible != open {
            self.alpha_start = self.alpha;
            self.visible = open;
            self.fade.restart(cx);
        }
        let duration = if open { 0.16 } else { 0.12 };
        let t = self.fade.time(duration, w, cx) / duration;
        self.alpha = self.alpha_start
            + (open as u8 as f32 - self.alpha_start) * super::family::standard_ease(t);
        self.spring
            .duration(open as u8 as f32, if open { enter } else { exit }, cx);
        // Once the exit fade finishes, an invisible spring tail must not intercept
        // clicks on the field underneath it.
        if !open && self.alpha <= 0. {
            0.
        } else {
            self.spring.get(w, cx).clamp(0., 1.)
        }
    }
    pub fn above(mut self) -> Self {
        self.above = true;
        self
    }
    pub fn at(&self, b: Bounds<Pixels>) {
        self.anchor.set(b)
    }
    pub fn anchor(&self) -> impl IntoElement + 'static {
        let bounds = self.anchor.clone();
        canvas(move |b, _, _| bounds.set(b), |_, _, _, _| ())
            .absolute()
            .inset_0()
    }
    pub fn anchor_bounds(&self) -> Bounds<Pixels> {
        self.anchor.get()
    }
    pub fn contains(&self, pos: Point<Pixels>) -> bool {
        self.panel_bounds.get().contains(&pos)
    }
    /// Position after layout so the trigger's hit target never moves when the popover appears.
    pub fn popup(
        &self,
        child: impl IntoElement,
        t: f32,
        open: bool,
        geometry: (f32, f32, f32),
        w: &Window,
    ) -> Div {
        let b = self.anchor.get();
        let view = w.viewport_size();
        let (width, estimate, travel) = geometry;
        let measured = self.panel_bounds.get();
        let h = if measured.size.height > px(1.) {
            measured.size.height
        } else {
            px(estimate)
        };
        let needed = h.min(px(160.));
        let fits_above = b.top() > needed + px(14.);
        let fits_below = view.height - b.bottom() > needed + px(14.);
        let above = if self.above && fits_above {
            true
        } else if !self.above && fits_below {
            false
        } else {
            b.top() > view.height - b.bottom()
        };
        let side = if above {
            Anchor::BottomLeft
        } else {
            Anchor::TopLeft
        };
        let y = if above {
            b.top() - px(6.) + px(travel * (1. - t))
        } else {
            b.bottom() + px(6.) - px(travel * (1. - t))
        };
        let bounds = self.panel_bounds.clone();
        let width = if width > 0. { px(width) } else { b.size.width };
        let available = (if above {
            b.top()
        } else {
            view.height - b.bottom()
        } - px(14.))
        .max(px(32.));
        let face = div()
            .id("form-popover-viewport")
            .max_h(available)
            .overflow_y_scroll()
            .w(width.min((view.width - px(16.)).max(px(1.))))
            .relative()
            .opacity(self.alpha)
            .child(child)
            .child(
                canvas(move |b, _, _| bounds.set(b), |_, _, _, _| ())
                    .absolute()
                    .inset_0(),
            )
            .when(!open, |d| {
                d.child(div().id("closing-form-menu").absolute().inset_0().occlude())
            });
        div().absolute().size(px(0.)).child(
            deferred(
                anchored()
                    .anchor(side)
                    .position(point(b.left(), y))
                    .snap_to_window_with_margin(px(8.))
                    .child(face),
            )
            .with_priority(3),
        )
    }
    /// Keep the backing surface alive independently of the faster exit of its contents.
    pub fn range_progress(&mut self, open: bool, w: &Window, cx: &App) -> f32 {
        if self.visible != open {
            self.alpha_start = self.alpha;
            self.visible = open;
            self.fade.restart(cx);
        }
        let (delay, duration) = if open { (0.07, 0.26) } else { (0., 0.12) };
        let elapsed = self.fade.time(delay + duration, w, cx);
        let t = ((elapsed - delay) / duration).clamp(0., 1.);
        self.alpha = self.alpha_start
            + (open as u8 as f32 - self.alpha_start) * super::family::standard_ease(t);
        self.spring
            .duration(open as u8 as f32, if open { 0.48 } else { 0.38 }, cx);
        self.spring.get(w, cx).clamp(0., 1.)
    }

    /// Grow a single 44px field into the measured panel without moving its layout slot.
    pub fn over_trigger(
        &self,
        (child, moving_label): (impl IntoElement, Option<Div>),
        t: f32,
        open: bool,
        open_width: f32,
        w: &Window,
        cx: &App,
    ) -> Div {
        let b = self.anchor_bounds();
        let available = w.viewport_size() - size(px(16.), px(16.));
        let width = px(open_width).min(available.width);
        let target_left = b.left().clamp(
            px(8.),
            (w.viewport_size().width - width - px(8.)).max(px(8.)),
        );
        let left = b.left() + (target_left - b.left()) * t;
        let measured = self.height.clone();
        let bounds = self.panel_bounds.clone();
        let full_height = if measured.get() > px(1.) {
            measured.get()
        } else {
            px(400.)
        };
        let height = b.size.height + (full_height.min(available.height) - b.size.height) * t;
        let p = Paint::get(cx);
        let backing = if open { 1. } else { (t * 6.).min(1.) };
        let shell = div()
            .debug_selector(|| "date-range-surface".into())
            .relative()
            .overflow_hidden()
            .rounded(crate::foundation::surface_radius(cx))
            .border_1()
            .border_color(p.line.opacity(backing))
            .bg(p.panel.opacity(backing))
            .w(b.size.width + (width - b.size.width) * t)
            .h(height)
            .when(open || self.alpha > 0., |el| {
                el.child(
                    div()
                        .absolute()
                        .left_0()
                        .top_0()
                        .w((width - px(2.)).max(px(1.)))
                        .on_children_prepainted(move |bounds, _, _| {
                            if let Some(b) = bounds.first() {
                                measured.set(b.size.height + px(2.));
                            }
                        })
                        .id("range-panel-scroll")
                        .max_h((available.height - px(2.)).max(px(1.)))
                        .overflow_y_scroll()
                        .opacity(self.alpha)
                        .child(child),
                )
            })
            .children(moving_label)
            .child(
                canvas(move |b, _, _| bounds.set(b), |_, _, _, _| ())
                    .absolute()
                    .inset_0(),
            );
        div().absolute().size(px(0.)).child(
            deferred(
                anchored()
                    .anchor(Anchor::TopLeft)
                    .position(point(left, b.top()))
                    .snap_to_window_with_margin(px(8.))
                    .child(shell),
            )
            .with_priority(3),
        )
    }
    pub fn wrap(
        &self,
        child: impl IntoElement,
        t: f32,
        open: bool,
        initial_height: f32,
        lift: f32,
    ) -> Div {
        let measured = self.height.clone();
        let height = self.height.get();
        let height = if height > px(1.) {
            height
        } else {
            px(initial_height)
        };
        div()
            .relative()
            .flex()
            .flex_col()
            .min_w_0()
            .overflow_hidden()
            .when(t < 0.9999, |el| {
                el.h(height * t)
                    .opacity(self.alpha)
                    .relative()
                    .top(px(-lift * (1. - t)))
            })
            .on_children_prepainted(move |b, _, _| {
                if let Some(b) = b.first() {
                    measured.set(b.size.height);
                }
            })
            .child(div().flex_none().min_w_0().child(child))
            .when(!open, |d| {
                d.child(div().id("closing-surface").absolute().inset_0().occlude())
            })
    }
}

/// A fixed baseline and a moving copy for changing digits. Shared character
/// positions stay put while the changed places roll in the direction of change.
#[derive(Default)]
pub struct RollingValue {
    shown: Option<SharedString>,
    previous: SharedString,
    direction: f32,
    clock: super::family::PhaseClock,
}
impl RollingValue {
    pub fn label(
        &mut self,
        next: impl Into<SharedString>,
        direction: f32,
        w: &Window,
        cx: &App,
    ) -> Div {
        let next = next.into();
        if self.shown.as_ref() != Some(&next)
            && let Some(old) = self.shown.replace(next.clone())
        {
            self.previous = old;
            self.direction = direction;
            self.clock.restart(cx);
        }
        let time = self.clock.time(0.24, w, cx);
        if time >= 0.24 {
            return div().child(next);
        }
        let in_t = super::family::ease(time / 0.24);
        let out_t = super::family::standard_ease(time / 0.14);
        let a: Vec<_> = self.previous.chars().collect();
        let b: Vec<_> = next.chars().collect();
        let count = a.len().max(b.len());
        let mut row = div().flex().items_center().h(px(20.)).overflow_hidden();
        for i in 0..count {
            let prev = a.get(i).map(char::to_string).unwrap_or_default();
            let next = b.get(i).map(char::to_string).unwrap_or_default();
            if prev == next {
                row = row.child(div().child(next));
                continue;
            }
            let width = super::family::measure(&prev.clone().into(), 14., w) * (1. - in_t)
                + super::family::measure(&next.clone().into(), 14., w) * in_t;
            row = row.child(
                div()
                    .relative()
                    .w(px(width))
                    .h(px(20.))
                    .child(
                        div()
                            .absolute()
                            .top(px(-6. * self.direction * out_t))
                            .opacity(1. - out_t)
                            .child(prev),
                    )
                    .child(
                        div()
                            .absolute()
                            .top(px(6. * self.direction * (1. - in_t)))
                            .opacity(in_t)
                            .child(next),
                    ),
            );
        }
        row
    }
}

/// Trace the two check segments in order. Mixed state interpolates both vertices
/// into a horizontal dash without replacing the glyph midway.
pub fn check_stroke(amount: f32, mixed: f32, side: f32, ink: Hsla) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let vertex = |x: f32, y: f32, dx: f32, dy: f32| {
                b.origin
                    + point(
                        px((x + (dx - x) * mixed) * side),
                        px((y + (dy - y) * mixed) * side),
                    )
            };
            let pts = [
                vertex(0.14, 0.52, 0.18, 0.5),
                vertex(0.42, 0.77, 0.50, 0.5),
                vertex(0.87, 0.24, 0.82, 0.5),
            ];
            let mut stroke = PathBuilder::stroke(px(1.65));
            stroke.move_to(pts[0]);
            for i in 0..2 {
                let end = if i == 0 {
                    (amount / 0.35).clamp(0., 1.)
                } else {
                    ((amount - 0.35) / 0.65).clamp(0., 1.)
                };
                if end > 0. {
                    stroke.line_to(pts[i] + (pts[i + 1] - pts[i]) * end);
                }
            }
            if amount > 0.
                && let Ok(path) = stroke.build()
            {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(side))
}

//! Civil calendar arithmetic without timezone or DST conversions in the selection path.
use super::{
    family::{Paint, Slide, Tone, face},
    form_chrome::*,
    glyph::{Glyph, transformed},
};
use gpui::{prelude::*, *};
use std::{cell::Cell, marker::PhantomData, rc::Rc};
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct CivilDate {
    pub year: i32,
    pub month: u8,
    pub day: u8,
}
impl CivilDate {
    pub fn new(year: i32, month: u8, day: u8) -> Option<Self> {
        let d = Self { year, month, day };
        ((1..=9999).contains(&year) && (1..=12).contains(&month) && day >= 1 && day <= d.days())
            .then_some(d)
    }
    fn days(self) -> u8 {
        match self.month {
            2 if self.year % 4 == 0 && (self.year % 100 != 0 || self.year % 400 == 0) => 29,
            2 => 28,
            4 | 6 | 9 | 11 => 30,
            _ => 31,
        }
    }
    fn serial(self) -> i64 {
        let m = self.month as i64;
        let y = self.year as i64 - i64::from(m <= 2);
        let era = y.div_euclid(400);
        let yo = y - era * 400;
        era * 146097 + yo * 365 + yo / 4 - yo / 100
            + (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5
            + i64::from(self.day)
            - 1
            - 719468
    }
    fn from_serial(s: i64) -> Self {
        let z = s + 719468;
        let era = z.div_euclid(146097);
        let doe = z - era * 146097;
        let y = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        let doy = doe - (365 * y + y / 4 - y / 100);
        let mp = (5 * doy + 2) / 153;
        let day = doy - (153 * mp + 2) / 5 + 1;
        let m = if mp < 10 { mp + 3 } else { mp - 9 };
        Self {
            year: (y + era * 400 + i64::from(m <= 2)) as i32,
            month: m as u8,
            day: day as u8,
        }
    }
    pub fn today_utc() -> Self {
        let t = web_time::SystemTime::now()
            .duration_since(web_time::UNIX_EPOCH)
            .unwrap_or_default();
        Self::from_serial((t.as_secs() / 86400) as i64)
    }
    pub fn add_days(self, n: i32) -> Self {
        Self::from_serial(self.serial() + i64::from(n))
    }
    pub fn add_months(self, n: i32) -> Self {
        let i = self.year * 12 + i32::from(self.month) - 1 + n;
        let mut d = Self {
            year: i.div_euclid(12).clamp(1, 9999),
            month: (i.rem_euclid(12) + 1) as u8,
            day: self.day,
        };
        d.day = d.day.min(d.days());
        d
    }
    pub fn weekday(self) -> usize {
        (self.serial() + 4).rem_euclid(7) as usize
    }
    pub fn format(self, cx: &App) -> String {
        if tr(cx, "en", "zh") == "zh" {
            format!("{}年{}月{}日", self.year, self.month, self.day)
        } else {
            format!(
                "{} {}, {}",
                &MONTHS[(self.month - 1) as usize][..3],
                self.day,
                self.year
            )
        }
    }
}
const MONTHS: [&str; 12] = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
];
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DateSpan {
    pub start: CivilDate,
    pub end: CivilDate,
}
impl DateSpan {
    pub fn new(a: CivilDate, b: CivilDate) -> Self {
        Self {
            start: a.min(b),
            end: a.max(b),
        }
    }
    fn label(self, zh: bool) -> String {
        let (a, b) = (self.start, self.end);
        if zh {
            let start = format!("{}年{}月{}日", a.year, a.month, a.day);
            if a == b {
                return start;
            }
            let end = if a.year != b.year {
                format!("{}年{}月{}日", b.year, b.month, b.day)
            } else if a.month != b.month {
                format!("{}月{}日", b.month, b.day)
            } else {
                format!("{}日", b.day)
            };
            format!("{start} – {end}")
        } else {
            let (ma, mb) = (
                &MONTHS[(a.month - 1) as usize][..3],
                &MONTHS[(b.month - 1) as usize][..3],
            );
            if a == b {
                format!("{ma} {}, {}", a.day, a.year)
            } else if a.year != b.year {
                format!("{ma} {}, {} – {mb} {}, {}", a.day, a.year, b.day, b.year)
            } else if a.month != b.month {
                format!("{ma} {} – {mb} {}, {}", a.day, b.day, b.year)
            } else {
                format!("{ma} {} – {}, {}", a.day, b.day, b.year)
            }
        }
    }
    pub fn days(self) -> usize {
        (self.end.serial() - self.start.serial() + 1) as usize
    }
}
/// Emitted when a selected date is removed using the field's Clear action.
pub struct DateCleared;
pub trait DateLayout: 'static {
    const FIELD: bool;
    const RANGE: bool;
}
#[derive(Default)]
struct RangeLabelSlots {
    trigger: Rc<Cell<Bounds<Pixels>>>,
    summary: Rc<Cell<Bounds<Pixels>>>,
}
impl RangeLabelSlots {
    fn probe(slot: &Rc<Cell<Bounds<Pixels>>>) -> impl IntoElement + 'static {
        let slot = slot.clone();
        canvas(move |bounds, _, _| slot.set(bounds), |_, _, _, _| ())
            .absolute()
            .inset_0()
    }

    fn flight(&self, progress: f32, label: Div) -> Div {
        let from = self.trigger.get();
        let to = self.summary.get();
        let to = if to.size.width > px(0.) { to } else { from };
        let origin = from.origin + (to.origin - from.origin) * progress;
        let width = from.size.width + (to.size.width - from.size.width) * progress;
        div().absolute().size(px(0.)).child(
            anchored().position(origin).snap_to_window().child(
                div()
                    .w(width.max(px(1.)))
                    .h(px(20.))
                    .overflow_hidden()
                    .child(label),
            ),
        )
    }
}
pub struct DateControl<L: DateLayout> {
    label: SharedString,
    help: SharedString,
    today: CivilDate,
    min: Option<CivilDate>,
    max: Option<CivilDate>,
    view: CivilDate,
    active: CivilDate,
    value: Option<DateSpan>,
    anchor: Option<CivilDate>,
    draft: Option<DateSpan>,
    open: bool,
    reveal: FormReveal,
    month_offset: Slide,
    edges: [Slide; 2],
    cursor: [Slide; 2],
    previous_date: Option<CivilDate>,
    value_label: RollingValue,
    range_label: RangeLabelSlots,
    close_after: Option<super::family::PhaseClock>,
    trigger: FocusHandle,
    grid: FocusHandle,
    _layout: PhantomData<L>,
}
impl<L: DateLayout> EventEmitter<DateCleared> for DateControl<L> {}
impl<L: DateLayout> EventEmitter<DateSpan> for DateControl<L> {}
impl<L: DateLayout> DateControl<L> {
    pub fn new(label: impl Into<SharedString>, today: CivilDate, cx: &mut Context<Self>) -> Self {
        Self {
            label: label.into(),
            help: "".into(),
            today,
            min: None,
            max: None,
            view: today,
            active: today,
            value: None,
            anchor: None,
            draft: None,
            open: !L::FIELD,
            reveal: FormReveal::new(!L::FIELD),
            month_offset: Slide::snappy((today.year * 12 + i32::from(today.month)) as f32),
            edges: [Slide::snappy(0.); 2],
            cursor: [Slide::snappy(0.); 2],
            previous_date: None,
            value_label: Default::default(),
            range_label: Default::default(),
            close_after: None,
            trigger: cx.focus_handle().tab_stop(true),
            grid: cx.focus_handle().tab_stop(true),
            _layout: PhantomData,
        }
    }
    pub fn with_value(mut self, value: DateSpan) -> Self {
        self.view = value.end;
        self.active = value.end;
        self.value = Some(value);
        self.month_offset
            .reset((value.end.year * 12 + i32::from(value.end.month)) as f32);
        self
    }
    /// Inclusive civil dates that may receive focus or be committed.
    pub fn with_bounds(mut self, min: Option<CivilDate>, max: Option<CivilDate>) -> Self {
        (self.min, self.max) = match (min, max) {
            (Some(lo), Some(hi)) if lo > hi => (Some(hi), Some(lo)),
            bounds => bounds,
        };
        self.active = self.bounded(self.active);
        self.view = self.active;
        self
    }
    fn bounded(&self, date: CivilDate) -> CivilDate {
        self.min
            .map_or(date, |lo| lo.max(date))
            .min(self.max.unwrap_or(CivilDate {
                year: 9999,
                month: 12,
                day: 31,
            }))
    }
    fn visible_month(&self, d: CivilDate, wide: bool) -> CivilDate {
        let key = |d: CivilDate| (d.year, d.month);
        if wide && key(d) > key(self.view) {
            if key(d) == key(self.view.add_months(1)) {
                self.view
            } else {
                d.add_months(-1)
            }
        } else {
            d
        }
    }
    pub fn with_description(mut self, s: impl Into<SharedString>) -> Self {
        self.help = s.into();
        self
    }
    pub fn value(&self) -> Option<DateSpan> {
        self.value
    }
    fn show(&mut self, w: &mut Window, cx: &mut Context<Self>) {
        self.open = true;
        self.anchor = None;
        self.draft = self.value;
        self.active = self.bounded(self.value.map_or(self.today, |r| r.end));
        self.view = if L::RANGE && w.viewport_size().width >= px(728.) {
            self.active.add_months(-1)
        } else {
            self.active
        };
        self.grid.focus(w, cx);
        self.close_after = None;
        self.month_offset
            .reset((self.view.year * 12 + i32::from(self.view.month)) as f32);
        cx.notify()
    }
    fn close(&mut self, w: &mut Window, cx: &mut Context<Self>) {
        self.close_after = None;
        if L::FIELD {
            self.open = false;
            self.trigger.focus(w, cx)
        }
        self.anchor = None;
        // Keep the last drawn range through the exit. Opening resets it from the committed value.
        if !L::RANGE {
            self.draft = None;
        }
        cx.notify()
    }
    fn commit(&mut self, value: DateSpan, w: &mut Window, cx: &mut Context<Self>) {
        if self.value != Some(value) {
            self.previous_date = self.value.map(|d| d.start);
            self.value = Some(value);
            cx.emit(value)
        }
        if L::FIELD && !L::RANGE && !super::family::disabled_motion(cx) {
            let mut c = super::family::PhaseClock::default();
            c.restart(cx);
            self.close_after = Some(c);
            cx.notify();
        } else {
            self.close(w, cx)
        }
    }
    fn day(&mut self, d: CivilDate, w: &mut Window, cx: &mut Context<Self>) {
        if self.bounded(d) != d {
            return;
        }
        self.active = d;
        self.view = self.visible_month(d, L::RANGE && w.viewport_size().width >= px(728.));
        if L::RANGE {
            if let Some(first) = self.anchor.take() {
                self.draft = Some(DateSpan::new(first, d))
            } else {
                self.anchor = Some(d);
                self.draft = Some(DateSpan::new(d, d))
            }
            cx.notify()
        } else {
            self.commit(DateSpan::new(d, d), w, cx)
        }
    }
    fn move_to(&mut self, d: CivilDate, cx: &mut Context<Self>) {
        self.active = d;
        self.view = d;
        if let Some(a) = self.anchor {
            self.draft = Some(DateSpan::new(a, d))
        }
        cx.notify()
    }
    fn key(&mut self, e: &KeyDownEvent, w: &mut Window, cx: &mut Context<Self>) {
        let d = self.active;
        let next = match e.keystroke.key.as_str() {
            "left" => d.add_days(-1),
            "right" => d.add_days(1),
            "up" => d.add_days(-7),
            "down" => d.add_days(7),
            "home" => d.add_days(-(d.weekday() as i32)),
            "end" => d.add_days(6 - d.weekday() as i32),
            "pageup" => d.add_months(-1),
            "pagedown" => d.add_months(1),
            "enter" | "space" => {
                self.day(d, w, cx);
                cx.stop_propagation();
                return;
            }
            "escape" => {
                self.close(w, cx);
                cx.stop_propagation();
                return;
            }
            _ => return,
        };
        let next = self.bounded(next);
        let wanted = self.visible_month(next, L::RANGE && w.viewport_size().width >= px(728.));
        self.move_to(next, cx);
        self.view = wanted;
        w.prevent_default();
        cx.stop_propagation()
    }
    fn month_strip(
        &self,
        month: CivilDate,
        second: bool,
        offset: f32,
        width: f32,
        w: &Window,
        cx: &Context<Self>,
    ) -> Div {
        let p = Paint::get(cx);
        let zh = tr(cx, "en", "zh") == "zh";
        let title = |m: CivilDate| {
            if zh {
                format!("{}年{}月", m.year, m.month)
            } else {
                format!("{} {}", MONTHS[(m.month - 1) as usize], m.year)
            }
        };
        let old = month.add_months(if offset > 0. { -1 } else { 1 });
        let heading = div()
            .relative()
            .flex_1()
            .min_w_0()
            .text_size(px(if L::RANGE { 14. } else { 16. }))
            .font_weight(FontWeight::MEDIUM)
            .when(offset.abs() > 0.001, |d| {
                d.child(
                    div()
                        .absolute()
                        .left(px((offset - offset.signum()) * 12.))
                        .opacity(offset.abs())
                        .child(title(old)),
                )
            })
            .child(
                div()
                    .relative()
                    .left(px(offset * 12.))
                    .opacity(1. - offset.abs())
                    .child(title(month)),
            );
        let nav = |next: bool| {
            let index = |d: CivilDate| (d.year, d.month);
            let outer = if L::RANGE && w.viewport_size().width >= px(728.) {
                self.view.add_months(1)
            } else {
                self.view
            };
            let disabled = if next {
                self.max.is_some_and(|hi| index(outer) >= index(hi))
            } else {
                self.min.is_some_and(|lo| index(self.view) <= index(lo))
            };
            let name = if next {
                tr(cx, "Next month", "下个月")
            } else {
                tr(cx, "Previous month", "上个月")
            };
            face(
                if next { "next" } else { "prev" },
                name,
                32.,
                crate::foundation::surface_radius(cx).into(),
                Tone::Clear,
                cx,
            )
            .size(px(32.))
            .when(disabled, |d| {
                d.aria_description(tr(cx, "Unavailable", "不可用"))
            })
            .tab_stop(!disabled)
            .when(disabled, |d| d.opacity(0.36).cursor_default())
            .hover(move |v| v.bg(p.hover))
            .child(transformed(
                Glyph::Down,
                14.,
                p.secondary,
                if next {
                    -std::f32::consts::FRAC_PI_2
                } else {
                    std::f32::consts::FRAC_PI_2
                },
                1.,
                (0., 0.),
                1.,
            ))
            .on_click(cx.listener(move |s, _, _, cx| {
                if !disabled {
                    s.move_to(s.bounded(s.view.add_months(if next { 1 } else { -1 })), cx)
                }
            }))
        };
        let mut head = if L::RANGE {
            row()
                .relative()
                .w_full()
                .h(px(32.))
                .justify_center()
                .child(heading.flex_none())
                .when(!second, |d| {
                    d.child(div().absolute().left_0().child(nav(false)))
                })
                .when(second || w.viewport_size().width < px(728.), |d| {
                    d.child(div().absolute().right_0().child(nav(true)))
                })
        } else {
            let controls = row()
                .gap(px(2.))
                .child(
                    button("today", tr(cx, "Today", "今天"), cx)
                        .on_click(cx.listener(|s, _, w, cx| s.day(s.today, w, cx))),
                )
                .child(nav(false))
                .child(nav(true));
            if width < 260. {
                col()
                    .gap(px(4.))
                    .child(heading.flex_none())
                    .child(row().justify_end().child(controls))
            } else {
                row()
                    .h(px(34.))
                    .w_full()
                    .justify_between()
                    .child(heading)
                    .child(controls)
            }
        };
        head = head.debug_selector(move || format!("calendar-head-{}", usize::from(second)));
        let gap = if L::RANGE { 0. } else { 4. };
        let mut labels = row()
            .gap(px(gap))
            .h(px(if L::RANGE { 28. } else { 24. }))
            .w_full();
        for (i, text) in (if zh {
            ["日", "一", "二", "三", "四", "五", "六"]
        } else {
            ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"]
        })
        .into_iter()
        .enumerate()
        {
            labels = labels.child(
                div()
                    .debug_selector(move || format!("weekday-{}-{i}", usize::from(second)))
                    .w(px((width - 6. * gap) / 7.))
                    .flex_none()
                    .text_center()
                    .text_color(p.faint)
                    .text_size(px(12.))
                    .child(text),
            );
        }
        let travel = if L::RANGE { 48. } else { width };
        let mut panes = div().relative().w_full().overflow_hidden();
        if offset.abs() > 0.0001 {
            panes = panes.child(
                div()
                    .absolute()
                    .top_0()
                    .left(px(
                        (offset - offset.signum()) * if L::RANGE { 36. } else { travel }
                    ))
                    .w_full()
                    .opacity(if L::RANGE { offset.abs() } else { 1. })
                    .child(self.month_grid(old, second, false, width, w, cx)),
            );
        }
        panes = panes.child(
            div()
                .relative()
                .left(px(offset * travel))
                .w_full()
                .opacity(if L::RANGE { 1. - offset.abs() } else { 1. })
                .child(self.month_grid(month, second, true, width, w, cx)),
        );
        col()
            .w(px(width))
            .max_w_full()
            .gap_0()
            .child(head)
            .child(labels.when(!L::RANGE, |d| d.mt(px(14.)).mb(px(6.))))
            .child(panes)
    }
    fn month_grid(
        &self,
        month: CivilDate,
        second: bool,
        live: bool,
        width: f32,
        w: &Window,
        cx: &Context<Self>,
    ) -> Div {
        let p = Paint::get(cx);
        let gap = if L::RANGE { 0. } else { 4. };
        let cell = (width - gap * 6.) / 7.;
        let mut grid = col().gap(px(gap)).w_full();
        let first = CivilDate { day: 1, ..month };
        let start = first.add_days(-(first.weekday() as i32));
        let span = if self.open && L::RANGE {
            self.draft.or(self.value)
        } else {
            self.value
        };
        let edge = [self.edges[0].get(w, cx), self.edges[1].get(w, cx)];
        let week_base = start.serial() as f32;
        let cursor = [self.cursor[0].get(w, cx), self.cursor[1].get(w, cx)];
        for week in 0..6 {
            let mut days = row().relative().gap(px(gap)).w_full().h(px(cell));
            let week_start = week_base + week as f32 * 7.;
            if L::RANGE && span.is_some() && edge[1] >= week_start && edge[0] < week_start + 7. {
                let x = (edge[0].max(first.serial() as f32) - week_start).clamp(0., 7.) / 7.;
                let month_end = CivilDate {
                    day: month.days(),
                    ..month
                };
                let end =
                    (edge[1].min(month_end.serial() as f32) - week_start + 1.).clamp(0., 7.) / 7.;
                days = days.child(
                    div()
                        .absolute()
                        .left(relative(x))
                        .w(relative((end - x).max(0.)))
                        .top(px(4.))
                        .bottom(px(4.))
                        .rounded(crate::foundation::surface_radius(cx))
                        .bg(p.hover),
                );
            }
            if !L::RANGE && self.value.is_some() {
                let rel_y = cursor[1] - ((week_base + 4.) / 7.).floor() - week as f32;
                if rel_y.abs() < 1. {
                    days = days.child(
                        div()
                            .absolute()
                            .top(px(rel_y * (cell + gap)))
                            .left(px(cursor[0] * (cell + gap)))
                            .size(px(cell))
                            .rounded(crate::foundation::surface_radius(cx))
                            .bg(p.bright),
                    )
                }
            }
            for day in 0..7 {
                let d = start.add_days(week * 7 + day);
                if L::RANGE && month.month != d.month {
                    days = days.child(div().w(px(cell)).flex_none());
                    continue;
                }
                let enabled = self.bounded(d) == d;
                let on = span.is_some_and(|s| s.start == d || s.end == d);
                let dname = d.format(cx);
                let b = face(
                    (
                        if live { "day" } else { "leaving-day" },
                        d.serial() as usize,
                    ),
                    dname,
                    cell,
                    crate::foundation::surface_radius(cx).into(),
                    Tone::Clear,
                    cx,
                )
                .tab_stop(false)
                .when(!enabled, |b| {
                    b.aria_description(tr(cx, "Unavailable", "不可用"))
                })
                .when(!enabled, |b| b.opacity(0.38).cursor_default())
                .when(live, |el| {
                    el.debug_selector(move || {
                        format!("calendar-cell-{}-{week}-{day}", usize::from(second))
                    })
                })
                .relative()
                .role(Role::GridCell)
                .aria_selected(on)
                .rounded(crate::foundation::surface_radius(cx))
                .w(px(cell))
                .flex_none()
                .bg(if on && L::RANGE {
                    p.bright
                } else {
                    transparent_black()
                })
                .text_color(
                    if on
                        && (L::RANGE
                            || ((cursor[0] - d.weekday() as f32).abs() < 0.55
                                && (cursor[1] - ((d.serial() as f32 + 4.) / 7.).floor()).abs()
                                    < 0.55))
                    {
                        p.inverse
                    } else if month.month != d.month {
                        p.faint
                    } else {
                        p.ink
                    },
                )
                .when(self.active == d && !on && self.grid.is_focused(w), |b| {
                    b.border_1().border_color(p.faint)
                })
                .when(!on && enabled, |b| b.hover(move |s| s.bg(p.hover)))
                .font_weight(if on || d == self.today {
                    FontWeight::MEDIUM
                } else {
                    FontWeight::NORMAL
                })
                .child(d.day.to_string())
                .when(d == self.today, |b| {
                    b.child(
                        div()
                            .absolute()
                            .bottom(px(4.))
                            .size(px(4.))
                            .rounded_full()
                            .bg(if on { p.inverse } else { p.ink }),
                    )
                })
                .when(live, |b| {
                    b.on_hover(cx.listener(move |s, over: &bool, _, cx| {
                        if *over
                            && enabled
                            && let Some(a) = s.anchor
                        {
                            s.draft = Some(DateSpan::new(a, d));
                            cx.notify()
                        }
                    }))
                    .on_click(cx.listener(move |s, _, w, cx| s.day(d, w, cx)))
                });
                days = days.child(b)
            }
            grid = grid.child(days)
        }
        grid
    }
}
impl<L: DateLayout> Render for DateControl<L> {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = Paint::get(cx);
        if let Some(c) = self.close_after
            && c.time(0.30, w, cx) >= 0.30
        {
            self.close(w, cx);
        }
        let progress = if L::RANGE {
            self.reveal.range_progress(self.open, w, cx)
        } else {
            self.reveal.sample(self.open, 0.26, 0.14, w, cx)
        };
        let target = (self.view.year * 12 + i32::from(self.view.month)) as f32;
        let from = self.month_offset.value(cx);
        if (target - from).abs() > 2. {
            self.month_offset.reset(target - (target - from).signum());
        }
        self.month_offset.duration(target, 0.42, cx);
        let offset = (target - self.month_offset.get(w, cx)).clamp(-1., 1.);
        let span = if L::RANGE && self.open {
            self.draft.or(self.value)
        } else {
            self.value
        };
        if let Some(v) = span {
            for (spring, d) in self.edges.iter_mut().zip([v.start, v.end]) {
                let val = d.serial() as f32;
                if (spring.value(cx) - val).abs() > 65. {
                    spring.reset(val);
                }
                spring.duration(val, 0.40, cx);
            }
            let end = v.end;
            let week = ((end.serial() as f32 + 4.) / 7.).floor();
            if (self.cursor[1].value(cx) - week).abs() > 6. {
                self.cursor[0].reset(end.weekday() as f32);
                self.cursor[1].reset(week);
            }
            self.cursor[0].duration(end.weekday() as f32, 0.42, cx);
            self.cursor[1].duration(week, 0.42, cx);
        }
        let compact = w.viewport_size().width < px(728.);
        let zh = tr(cx, "en", "zh") == "zh";
        let available = (f32::from(w.viewport_size().width) - 16.).max(1.);
        let preferred =
            |title: &str| super::family::measure(&title.to_owned().into(), 14., w).ceil() + 82.;
        let format_range = |r: DateSpan| {
            let label = r.label(zh);
            if preferred(&label) <= available {
                label
            } else if r.start.year == r.end.year {
                format!(
                    "{}/{}/{} – {}/{}",
                    r.start.year, r.start.month, r.start.day, r.end.month, r.end.day
                )
            } else {
                format!(
                    "{}/{}/{} – {}/{}/{}",
                    r.start.year, r.start.month, r.start.day, r.end.year, r.end.month, r.end.day
                )
            }
        };
        let title = match self.value {
            Some(r) if L::RANGE => format_range(r),
            Some(r) => r.start.format(cx),
            None => tr(cx, "Select date", "选择日期").into(),
        };
        let flying = L::RANGE
            && if self.open {
                progress < 1.
            } else {
                progress > 0.
            };
        let displayed = if L::RANGE && self.open {
            self.draft
                .map_or_else(|| tr(cx, "No dates", "未选日期").into(), format_range)
        } else {
            title.clone()
        };
        let direction = if self
            .previous_date
            .is_some_and(|d| self.value.is_some_and(|r| r.start < d))
        {
            -1.
        } else {
            1.
        };
        // The same shaped label occupies exactly one of trigger, moving layer, or footer.
        let mut value_label = L::FIELD.then(|| {
            self.value_label
                .label(displayed.clone(), direction, w, cx)
                .debug_selector(|| "calendar-visible-value".into())
                .when(L::RANGE, |el| {
                    el.font_weight(FontWeight::MEDIUM)
                        .text_color(p.ink)
                        .text_size(px(14.))
                        .line_height(px(20.))
                        .whitespace_nowrap()
                })
        });
        let closed = preferred(&title).max(220.).min(available);
        let open_width = if compact {
            352_f32.min(available)
        } else {
            712.
        };
        let width = if L::RANGE {
            closed
        } else if L::FIELD {
            340.
        } else {
            328.
        };
        let mut root = section(width, cx)
            .relative()
            .id("date")
            .on_mouse_down_out(cx.listener(|s, e: &MouseDownEvent, w, cx| {
                if L::FIELD && s.open && !s.reveal.contains(e.position) {
                    s.close(w, cx)
                }
            }));
        if L::FIELD {
            root = root
                .when(!self.label.is_empty(), |r| r.child(self.label.clone()))
                .child(
                    field("open", title.clone(), cx)
                        .relative()
                        .debug_selector(|| "date-trigger".into())
                        .gap(px(9.))
                        .child(self.reveal.anchor())
                        .track_focus(&self.trigger)
                        .when(L::RANGE, |b| {
                            b.h(px(44.))
                                .opacity((1. - progress * 1.6).clamp(0., 1.))
                                .overflow_hidden()
                                .tab_stop(!self.open)
                        })
                        .aria_expanded(self.open)
                        .child(
                            div()
                                .debug_selector(|| "date-leading".into())
                                .flex_none()
                                .size(px(16.))
                                .child(calendar_mark(p.faint)),
                        )
                        .child(
                            div()
                                .debug_selector(|| "date-value".into())
                                .flex_1()
                                .min_w_0()
                                .overflow_hidden()
                                .whitespace_nowrap()
                                .h(px(20.))
                                .relative()
                                .when(L::RANGE, |el| {
                                    el.child(RangeLabelSlots::probe(&self.range_label.trigger))
                                })
                                .when(!L::RANGE || (!self.open && !flying), |el| {
                                    el.children(value_label.take())
                                }),
                        )
                        .child(
                            div()
                                .debug_selector(|| "date-trailing".into())
                                .flex_none()
                                .size(px(16.))
                                .child(super::glyph::transformed(
                                    Glyph::Down,
                                    16.,
                                    p.faint,
                                    std::f32::consts::PI * progress,
                                    1.,
                                    (0., 0.),
                                    1.,
                                )),
                        )
                        .on_key_down(cx.listener(|s, e: &KeyDownEvent, w, cx| {
                            if !s.open
                                && matches!(e.keystroke.key.as_str(), "down" | "enter" | "space")
                            {
                                s.show(w, cx);
                                w.prevent_default();
                                cx.stop_propagation()
                            }
                        }))
                        .on_click(cx.listener(|s, _, w, cx| {
                            if s.open {
                                s.close(w, cx)
                            } else {
                                s.show(w, cx)
                            }
                        })),
                )
        }
        if self.open || progress > 0. {
            let pop_width = if w.viewport_size().width <= px(360.) {
                f32::from(self.reveal.anchor_bounds().size.width)
                    .max(1.)
                    .min(available)
            } else {
                320.
            };
            let pad = if L::RANGE {
                if compact { 8. } else { 10. }
            } else if L::FIELD && w.viewport_size().width > px(360.) {
                16.
            } else {
                12.
            };
            let grid_width = if L::RANGE {
                if compact {
                    (((open_width - 24.) / 7.).floor().clamp(1., 42.)) * 7.
                } else {
                    252.
                }
            } else if L::FIELD {
                (pop_width - pad * 2. - 2.).max(1.)
            } else {
                width.min(available) - pad * 2. - 2.
            };
            let mut body = panel(cx)
                .when(L::RANGE, |p| {
                    p.border_0().bg(transparent_black()).relative().occlude()
                })
                .when(!L::RANGE, |p| p.shadow_lg())
                .id("grid")
                .track_focus(&self.grid)
                .on_key_down(cx.listener(Self::key))
                .p(px(pad));
            let mut layout = if compact { col() } else { row().items_start() };
            if L::RANGE {
                let mut presets = if compact {
                    row().gap(px(4.)).id("presets").overflow_x_scroll()
                } else {
                    col().gap(px(2.)).id("presets")
                };
                let today = self.today;
                let month = CivilDate { day: 1, ..today };
                let previous = month.add_months(-1);
                let q = (today.month - 1) / 3 * 3 + 1;
                for (i, (en, zh, start, end)) in [
                    ("Today", "今天", today, today),
                    ("Yesterday", "昨天", today.add_days(-1), today.add_days(-1)),
                    ("Last 7 days", "近 7 天", today.add_days(-6), today),
                    ("Last 30 days", "近 30 天", today.add_days(-29), today),
                    ("This month", "本月", month, today),
                    ("Last month", "上月", previous, month.add_days(-1)),
                    (
                        "This quarter",
                        "本季度",
                        CivilDate { month: q, ..month },
                        today,
                    ),
                    (
                        "Year to date",
                        "本年",
                        CivilDate { month: 1, ..month },
                        today,
                    ),
                ]
                .into_iter()
                .enumerate()
                {
                    let chosen = DateSpan::new(self.bounded(start), self.bounded(end));
                    presets = presets.child(
                        button(("preset", i), tr(cx, en, zh), cx)
                            .when(self.draft == Some(chosen), |e| e.bg(p.hover))
                            .on_click(cx.listener(move |s, _, _, cx| {
                                let end = chosen.end;
                                s.anchor = None;
                                s.active = end;
                                s.view = if compact { end } else { end.add_months(-1) };
                                s.draft = Some(chosen);
                                cx.notify()
                            })),
                    );
                }
                layout = layout.child(presets);
            }
            let mut months = row()
                .justify_center()
                .gap(px(24.))
                .items_start()
                .min_w_0()
                .child(self.month_strip(self.view, false, offset, grid_width, w, cx));
            if L::RANGE && !compact {
                months = months.child(self.month_strip(
                    self.view.add_months(1),
                    true,
                    offset,
                    grid_width,
                    w,
                    cx,
                ))
            }
            body = body.child(layout.child(months));
            if L::RANGE {
                let cancel = tr(cx, "Cancel", "取消");
                let apply = tr(cx, "Apply", "应用");
                let text_width =
                    |text: &str| super::family::measure(&text.to_owned().into(), 14., w).ceil();
                let actions_width = text_width(cancel) + text_width(apply) + 2. * 18. + 8.;
                let summary_width = self.draft.map_or(0., |v| text_width(&format_range(v)));
                let stack = summary_width + 8. + actions_width > open_width - 2. * pad - 2.;
                let summary = col()
                    .gap_0()
                    .when(!stack, |el| el.flex_1())
                    .child(
                        div()
                            .relative()
                            .h(px(20.))
                            .w_full()
                            .overflow_hidden()
                            .debug_selector(|| "range-summary-slot".into())
                            .child(RangeLabelSlots::probe(&self.range_label.summary))
                            .when(!flying && self.open, |el| el.children(value_label.take())),
                    )
                    .when_some(self.draft, |s, v| {
                        s.child(hint(format!("{} {}", v.days(), tr(cx, "days", "天")), cx))
                    });
                let actions = row()
                    .justify_end()
                    .flex_none()
                    .child(
                        button("cancel", cancel, cx)
                            .on_click(cx.listener(|s, _, w, cx| s.close(w, cx))),
                    )
                    .child(
                        button("apply", apply, cx)
                            .bg(p.bright)
                            .text_color(p.inverse)
                            .on_click(cx.listener(|s, _, w, cx| {
                                if let Some(r) = s.draft {
                                    s.commit(r, w, cx)
                                }
                            })),
                    );
                let footer = if stack {
                    col().gap(px(6.))
                } else {
                    row().justify_between()
                };
                body = body
                    .child(footer.child(summary).child(actions))
                    .when(!self.open, |panel| {
                        panel.child(
                            div()
                                .id("range-exit")
                                .absolute()
                                .inset_0()
                                .occlude()
                                .on_click(cx.listener(|s, e: &ClickEvent, w, cx| {
                                    if s.reveal.anchor_bounds().contains(&e.position()) {
                                        s.show(w, cx);
                                        cx.stop_propagation();
                                    }
                                })),
                        )
                    });
            }
            if L::FIELD && !L::RANGE {
                let status = self.value.map_or_else(
                    || tr(cx, "Choose a day", "选择一天").to_owned(),
                    |v| format!("{} {}", tr(cx, "Selected", "已选择"), v.start.format(cx)),
                );
                body = body.child(
                    row()
                        .justify_between()
                        .mt(px(6.))
                        .pt(px(10.))
                        .border_t_1()
                        .border_color(p.line)
                        .child(
                            button("clear-date", tr(cx, "Clear", "清除"), cx)
                                .h(px(25.))
                                .text_size(px(12.))
                                .on_click(cx.listener(|s, _, w, cx| {
                                    if s.value.take().is_some() {
                                        cx.emit(DateCleared);
                                    }
                                    s.close(w, cx)
                                })),
                        )
                        .child(hint(status, cx)),
                );
            }
            root = if L::RANGE {
                root.child(
                    self.reveal.over_trigger(
                        (
                            body,
                            value_label
                                .take()
                                .map(|label| self.range_label.flight(progress, label)),
                        ),
                        progress,
                        self.open,
                        open_width,
                        w,
                        cx,
                    ),
                )
            } else if L::FIELD {
                root.child(
                    self.reveal
                        .popup(body, progress, self.open, (pop_width, 407., 8.), w),
                )
            } else {
                root.child(self.reveal.wrap(
                    body,
                    progress,
                    self.open,
                    if L::RANGE { 375. } else { 300. },
                    if L::RANGE { 0. } else { 8. },
                ))
            }
        }
        root.when(!self.help.is_empty(), |r| {
            r.child(hint(self.help.clone(), cx).opacity(1. - progress))
        })
        .when(L::RANGE, |r| {
            r.when_some(self.value, |r, v| {
                r.child(
                    hint(
                        format!("{} {}", v.days(), tr(cx, "days selected", "天已选")),
                        cx,
                    )
                    .opacity(1. - progress),
                )
            })
        })
    }
}
#[cfg(test)]
mod tests {
    use super::{CivilDate, DateSpan};
    #[test]
    fn civil_boundaries() {
        let leap = CivilDate::new(2024, 2, 29).unwrap();
        assert_eq!(leap.add_months(12), CivilDate::new(2025, 2, 28).unwrap());
        assert!(CivilDate::new(2100, 2, 29).is_none());
        assert_eq!(CivilDate::new(1970, 1, 1).unwrap().weekday(), 4);
        assert_eq!(DateSpan::new(leap, leap.add_days(-6)).days(), 7)
    }
}
